function render(){ $('#nav').innerHTML=pages.map(([p,n],i)=>`<button data-go="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${n}</button>`).join('');$('#app').innerHTML=views[page]()+footer();bind(); }
const views={
home:()=>`<div class="hero"><div><span class="eyebrow">Media pembelajaran · Profesi Ners</span><h1>Belajar merawat.<br>Memahami lansia.</h1><p class="sub">Hubungkan pengkajian, penalaran klinik, dan praktik yang berpusat pada lansia—dengan refleksi dan bimbingan di setiap tahap.</p><div class="actions"><button class="btn" data-go="sop">Mulai dari SOP</button><button class="btn light" data-go="logbook">Buka logbook</button></div></div><div class="hero-art"><span class="eyebrow">Alur belajar</span><strong>01—04</strong><div class="step">Pelajari SOP & video <span>01</span></div><div class="step">Simulasi / praktik terawasi <span>02</span></div><div class="step">Dokumentasi & refleksi <span>03</span></div><div class="step">Umpan balik & asesmen ulang <span>04</span></div></div></div><div class="grid">${[['149','Diagnosis SDKI','Jelajahi diagnosis, sumber, dan pasangan luaran–intervensi.','catalog'],['17','Instrumen gerontik','Pilih pengkajian berdasarkan kebutuhan dan indikasi lansia.','logbook'],['02','Video awal','Materi dari kanal YouTube Amzal Mortin Andas.','video']].map(([n,t,s,p])=>`<div class="card"><span class="num">${n}</span><h3>${t}</h3><p>${s}</p><button class="btn light" data-go="${p}">Jelajahi →</button></div>`).join('')}</div><div class="section card"><h2>Satu perjalanan belajar, bukti yang bermakna.</h2><p>Catatan tindakan menunjukkan pengalaman. Observasi dan umpan balik pembimbing menunjukkan perkembangan kompetensi. Simulasi dan praktik klinik dicatat terpisah.</p><a href="https://andazmortin88.github.io/tryoutnew/#tips-ukom" target="_blank" rel="noopener noreferrer">Lanjut ke latihan UKOM ↗</a></div>`,
dashboard:()=>{let verified=db.logs.filter(x=>x.status==='Terverifikasi'),days=new Set(db.logs.filter(x=>x.status==='Terverifikasi'&&x.context==='Praktik klinik').map(x=>x.date)).size;return pageTitle('Perkembangan belajar','Dashboard pembelajaran.','Angka berasal dari catatan demo pada browser ini; belum merupakan nilai akademik atau rekap mahasiswa sebenarnya.')+`<div class="grid">${[[days+'/10','Hari logbook klinik terverifikasi'],[db.reflections.filter(x=>x.status==='Terverifikasi').length+'/2','Refleksi mingguan terverifikasi'],[db.attendance.filter(x=>x.status==='Terverifikasi'&&x.presence==='Hadir').length,'Shift hadir terverifikasi'],[verified.length,'Catatan kegiatan terverifikasi'],[db.logs.filter(x=>x.status==='Diajukan').length,'Logbook menunggu review'],[new Set(verified.filter(x=>x.context==='Praktik klinik'&&x.outcome==='Kompeten dalam supervisi').map(x=>x.skill)).size,'Target dengan bukti kompeten klinik']].map(([n,t])=>`<div class="card"><span class="num">${n}</span><p>${t}</p></div>`).join('')}</div><div class="section card"><h2>Rencana periode</h2><p>2 minggu · Senin–Jumat · Pagi / Siang · Wisma A–D. Target jam dan jadwal aktual disahkan koordinator; jumlah entri absensi tidak otomatis membuktikan 70 jam praktik.</p><button class="btn" data-go="${teacher()?'review':'logbook'}">${teacher()?'Periksa pengajuan':'Catat pembelajaran hari ini'}</button></div>`;},
sop:()=>pageTitle('Sumber belajar','SOP lansia & dewasa.','Kurasi awal dari perawat.org. Pilihan teratas relevan untuk pembelajaran dewasa/lansia; kesesuaian pasien dan SOP mitra tetap ditinjau pembimbing.')+`<input class="search" id="sopSearch" aria-label="Cari SOP" placeholder="Cari SOP atau prosedur"><label for="sopFilter">Kelompok materi</label><select id="sopFilter"><option value="priority">Prioritas lansia & dewasa</option><option value="all">Semua SOP sumber</option></select><div class="grid section" id="sopList"></div><div class="banner">Materi mandi lansia, ganti popok, kebersihan mulut dan luka dekubitus masuk rencana kurasi/penyusunan. Isi prosedurnya belum diaktifkan sebelum telaah dosen dan mitra panti.</div><a href="https://perawat.org/category/sop/" target="_blank" rel="noopener noreferrer">Buka katalog sumber perawat.org ↗</a>`,
video:()=>pageTitle('Belajar melalui demonstrasi','Video pembelajaran.','Dua video awal dari kanal Bapak. Pemutar pertama berhasil dimuat; video kedua belum tersedia pada penyematan di lingkungan uji. Pemetaan kompetensi ditinjau pengajar.')+`<div class="two">${['rMefrH5vxL8','JLAYF5seIv0'].map((id,i)=>`<article class="card"><div class="eyebrow">Video pembelajaran ${i+1}</div><h3>${i===0?'Intervensi untuk kesepian lansia di panti':'Video kedua — periksa akses'}</h3><button class="video" data-video="${id}" aria-label="Muat video pembelajaran ${i+1}">▶ Muat pemutar YouTube<br><small>Pemutar memerlukan internet</small></button><p class="tiny">ID video: ${id} · Pemetaan kompetensi menunggu tinjauan pengajar.</p>${i===1?'<div class="banner">Penyematan menampilkan “This video is unavailable” saat uji 12 November 2026. Periksa visibilitas dan izin semat melalui YouTube Studio; tautan sumber tetap tersedia.</div>':''}<a target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/watch?v=${id}">Buka di YouTube ↗</a></article>`).join('')}</div><div class="card section"><h2>Sebelum dan setelah menonton</h2><p>Apa tujuan tindakan? Bagaimana kondisi lansia memengaruhi keputusan? Bagian mana yang memerlukan supervisi? Apa yang berubah dari pemahaman awal Anda?</p><button class="btn light" data-go="reflection">Tulis refleksi</button><p class="tiny">Menonton video tidak mengubah status kompetensi menjadi terverifikasi.</p></div>`,
catalog:()=>pageTitle('Referensi diagnosis','149 SDKI–SLKI–SIKI.','Snapshot sumber 8 November 2026. Seluruh entri merupakan referensi pembelajaran yang perlu ditelaah terhadap edisi resmi prodi sebelum penerapan klinik.')+`<div class="two"><div class="card"><input id="dxSearch" class="search" placeholder="Cari kode atau diagnosis" aria-label="Cari diagnosis"><select id="dxFilter" aria-label="Filter diagnosis"><option value="all">Seluruh 149 diagnosis</option><option value="gerontik">Pilihan relevan gerontik</option></select><p id="dxCount" class="tiny"></p><div id="dxList" class="catalog"></div></div><div id="dxDetail" class="card"></div></div>`,
logbook:()=>pageTitle('Pengalaman → refleksi → kompetensi','Logbook gerontik.','Pilih target, catat tindakan dan hasil, lalu ajukan kepada pembimbing. Gunakan data simulasi tanpa identitas pasien.')+`<div class="two"><div class="card"><h2>Katalog kompetensi</h2><input id="skillSearch" class="search" placeholder="Cari keterampilan atau instrumen" aria-label="Cari kompetensi"><p class="tiny">${DATA.competencies.length} target draf · 17 instrumen terpisah · frekuensi sesuai RPS/indikasi</p><div class="catalog" id="skillList"></div></div><div class="card"><h2>Catat pengalaman</h2><form id="logForm"><div class="banner" id="chosenSkill"></div><div class="fields"><div><label for="logDate">Tanggal</label><input id="logDate" name="date" type="date" required max="${today()}" value="${today()}"></div><div><label for="logShift">Shift</label><select id="logShift" name="shift"><option>Pagi</option><option>Siang</option></select></div><div><label for="logRoom">Wisma</label><select id="logRoom" name="room">${['A','B','C','D'].map(x=>`<option>Wisma ${x}</option>`).join('')}</select></div><div><label for="context">Konteks</label><select id="context" name="context"><option>Simulasi</option><option>Praktik klinik</option></select></div></div><label for="roleAction">Peran mahasiswa</label><select id="roleAction" name="action"><option>Mengamati</option><option>Melakukan simulasi</option><option>Melakukan dengan supervisi</option></select><label for="supervisor">Pembimbing yang mengamati</label><input id="supervisor" name="supervisor" placeholder="Nama pembimbing demo" required maxlength="100"><label for="summary">Ringkasan tindakan dan hasil</label><textarea id="summary" name="summary" required maxlength="3000" placeholder="Peran, respons lansia/manekin, temuan dan tindak lanjut. Tanpa identitas pasien."></textarea><label for="reflection">Refleksi dan rencana perbaikan</label><textarea id="reflection" name="reflection" required maxlength="3000" placeholder="Pemahaman awal, hal yang dipelajari, risiko, dan langkah perbaikan."></textarea><div class="actions"><button type="submit" name="intent" value="draft" class="btn light">Simpan draf</button><button type="submit" name="intent" value="submit" class="btn">Ajukan review</button></div></form></div></div><div class="section card"><h2>Riwayat logbook demo</h2>${records('logs')}</div>`,
reflection:()=>pageTitle('Belajar dari pengalaman','Refleksi mingguan.','Dua refleksi per stase. Uraikan perubahan pemahaman dan tindakan berikutnya, bukan sekadar daftar kegiatan.')+`<div class="two"><form class="card" id="reflectionForm"><h2>Catat refleksi</h2><label for="week">Minggu</label><select id="week" name="week"><option value="1">Minggu 1</option><option value="2">Minggu 2</option></select><label for="refText">Pengalaman, asumsi awal, bukti, dan perubahan</label><textarea name="text" id="refText" required maxlength="5000" placeholder="Apa yang terjadi? Asumsi apa tentang lansia yang perlu ditinjau? Bukti/umpan balik apa yang mengubah pemahaman Anda?"></textarea><label for="refPlan">Rencana tindak lanjut</label><textarea name="plan" id="refPlan" required maxlength="3000"></textarea><button class="btn" type="submit">Ajukan refleksi</button></form><div class="card"><h2>Riwayat refleksi</h2>${records('reflections')}</div></div>`,
attendance:()=>pageTitle('Kedisiplinan & akuntabilitas','Daftar hadir praktik.','Laporan mandiri tanpa GPS. Kehadiran dinyatakan terverifikasi setelah diperiksa pembimbing; satu laporan per tanggal dan shift.')+`<div class="two"><form class="card" id="attendanceForm"><h2>Catat dinas</h2><label for="attDate">Tanggal · Senin–Jumat</label><input id="attDate" name="date" type="date" max="${today()}" value="${today()}" required><div class="fields"><div><label for="attShift">Shift</label><select id="attShift" name="shift"><option>Pagi</option><option>Siang</option></select></div><div><label for="attRoom">Wisma</label><select id="attRoom" name="room">${['A','B','C','D'].map(x=>`<option>Wisma ${x}</option>`).join('')}</select></div><div><label for="attStart">Jam masuk</label><input id="attStart" name="start" type="time"></div><div><label for="attEnd">Jam keluar</label><input id="attEnd" name="end" type="time"></div></div><label for="presence">Status kehadiran</label><select id="presence" name="presence"><option>Hadir</option><option>Izin</option><option>Sakit</option></select><label for="attNote">Catatan / alasan</label><textarea id="attNote" name="note" maxlength="2000" placeholder="Pre-conference, kegiatan atau alasan izin/sakit."></textarea><button type="submit" class="btn">Ajukan kehadiran</button></form><div class="card"><h2>Riwayat laporan dinas</h2>${records('attendance')}</div></div>`,
skin:()=>pageTitle('Dokumentasi terstruktur','Integritas kulit & luka.','Contoh format pengkajian untuk ditelaah dosen. Bukan instrumen penilaian luka tervalidasi; diagnosis tidak ditentukan otomatis.')+`<form id="skinForm" class="card"><div class="fields"><div><label for="skinDate">Tanggal</label><input name="date" id="skinDate" type="date" max="${today()}" value="${today()}" required></div><div><label for="caseCode">Kode kasus simulasi</label><input id="caseCode" name="caseCode" required maxlength="40" placeholder="SIM-001"></div></div><label for="skinStatus">Kondisi kulit umum dan lokasi</label><textarea id="skinStatus" name="skinStatus" required maxlength="2000" placeholder="Keutuhan, warna, kelembapan, keluhan dan lokasi; tulis temuan aktual."></textarea><label for="wound">Temuan luka jika ada</label><textarea id="wound" name="wound" maxlength="2000" placeholder="Lokasi, panjang × lebar × kedalaman (cm), dasar luka, eksudat, tepi, kulit sekitar, nyeri. Bila tidak ada luka, tulis tidak ada."></textarea><label for="skinPlan">Respons, eskalasi dan tindak lanjut pembimbing</label><textarea id="skinPlan" name="plan" required maxlength="2000"></textarea><div class="actions"><button class="btn">Simpan contoh pengkajian</button><button type="button" class="btn light" data-go="catalog">Telaah diagnosis terkait</button></div></form><div class="card section"><h2>Dokumentasi demo</h2>${records('skin')}</div>`,
review:()=>pageTitle('Umpan balik yang dapat ditindaklanjuti','Review pembimbing.','Panel demonstrasi. Pada versi produksi hanya dosen/preseptor yang ditugaskan boleh mengakses dan menilai mahasiswa terkait.')+(teacher()?`<div class="banner">Peran demo aktif: dosen / preseptor. Seluruh keputusan di sini hanya simulasi pada browser ini.</div>`:`<div class="banner">Ganti pilihan peran di kanan atas menjadi “Dosen / preseptor · demo” untuk mencoba penilaian.</div>`)+['logs','reflections','attendance'].map((k,i)=>`<div class="card section"><h2>${['Logbook kompetensi','Refleksi mingguan','Kehadiran'][i]}</h2>${records(k,true)}</div>`).join(''),
matrix:()=>pageTitle('Rancangan akademik','Target & penilaian.','Selaras dengan draf RPS PPKG UBS 2026/2027 yang masih menunggu pengesahan CPL dan prodi.')+`<div class="grid"><div class="card"><span class="num">10 + 2</span><h3>Logbook & refleksi</h3><p>10 catatan harian dan dua refleksi mingguan. Pengalaman tindakan dicatat sebagai bukti di dalam periode tersebut.</p></div><div class="card"><span class="num">2</span><h3>Asuhan individu</h3><p>Satu kasus per minggu; subjek berbeda jika tersedia dan sesuai prioritas klinik.</p></div><div class="card"><span class="num">70 + 20</span><h3>Jam pembelajaran</h3><p>70 jam langsung dan 20 jam terstruktur/mandiri. Rekap waktu aktual diverifikasi pembimbing.</p></div></div><div class="card section scroll"><h2>Bobot penilaian dari draf RPS</h2><table><thead><tr><th>Komponen</th><th>Bobot</th></tr></thead><tbody>${[['Klinik terobservasi: mini-CEX 15; DOPS 10; BST 5',30],['Dua asuhan digital',25],['Uji/presentasi kasus dan EBN',15],['TAK / edukasi kelompok',10],['Portofolio / logbook',10],['Profesionalisme dan keselamatan',10]].map(([t,n])=>`<tr><td>${t}</td><td>${n}%</td></tr>`).join('')}</tbody></table><p class="tiny">Belum ada kalkulasi nilai akhir atau keputusan lulus pada preview. Rubrik 0–4 memerlukan bukti observasi; batas lulus dan kebijakan remediasi ditetapkan prodi.</p></div><div class="card section scroll"><h2>Matriks target draf</h2><table><thead><tr><th>Kode lokal</th><th>Domain / kompetensi</th><th>Target</th></tr></thead><tbody>${DATA.competencies.map(c=>`<tr><td>${c.id}</td><td>${esc(c.group)}<br><strong>${esc(c.name)}</strong></td><td>${esc(c.target)}</td></tr>`).join('')}</tbody></table></div><div class="card section"><h2>Data demo & portofolio</h2><p>Ekspor hanya memuat catatan simulasi di browser ini. Data mahasiswa dan arsip aplikasi produksi tidak diakses.</p><div class="actions"><button id="exportJson" class="btn">Unduh data demo JSON</button><button id="exportCsv" class="btn light">Unduh logbook CSV</button><button id="print" class="btn light">Cetak tampilan</button><button id="reset" class="btn light">Hapus data demo</button></div></div>`
};
function records(key,review=false){const list=db[key].filter(x=>!review||['Diajukan','Perlu revisi','Terverifikasi'].includes(x.status));if(!list.length)return '<div class="blank">Belum ada catatan demo.</div>';return list.slice().reverse().map(x=>`<article class="record"><div>${badge(x.status||'Draf')} <span class="tiny">${esc(x.date||'Minggu '+x.week)} ${esc(x.shift||'')} · ${esc(x.room||'')}</span></div><h3>${esc(x.skill?DATA.competencies.find(c=>c.id===x.skill)?.name:x.week?'Refleksi minggu '+x.week:x.caseCode||x.presence)}</h3>${x.start?`<p class="tiny">Jam: ${esc(x.start)}–${esc(x.end)}${x.late?' · Dilaporkan setelah tanggal kegiatan':''}</p>`:''}${x.corrections?.map(c=>`<div class="banner">Koreksi mahasiswa: ${esc(c.text)}</div>`).join('')||''}${x.context?`<span class="tag gray">${esc(x.context)} · ${esc(x.action)}</span>`:''}<p>${esc(x.summary||x.text||x.note||x.skinStatus||'')}</p>${x.reflection||x.plan?`<p class="tiny">Refleksi / tindak lanjut: ${esc(x.reflection||x.plan)}</p>`:''}${x.wound?`<p>${esc(x.wound)}</p>`:''}${x.reviews?.map(r=>`<div class="banner"><strong>Review demo · ${esc(r.status)}</strong><br>${esc(r.comment)}${r.score!==undefined?`<br>Skor demonstrasi: ${r.score}/4 · ${esc(r.outcome)}`:''}</div>`).join('')||''}${!review&&['Draf','Perlu revisi'].includes(x.status)&&key==='logs'?`<button class="btn light" data-edit="${x.id}">Buka dan revisi</button>`:''}${!review&&x.status==='Perlu revisi'&&['reflections','attendance'].includes(key)?`<form class="resubmitForm" data-key="${key}" data-id="${x.id}"><label>Koreksi / tindak lanjut<textarea name="correction" required maxlength="3000"></textarea></label><button class="btn light">Ajukan kembali</button></form>`:''}${review&&teacher()&&x.status==='Diajukan'?reviewForm(key,x):''}</article>`).join('')}
function reviewForm(key,x){return `<form class="reviewForm" data-key="${key}" data-id="${x.id}"><label>Umpan balik pembimbing<textarea name="comment" required maxlength="3000" placeholder="Kekuatan, bukti observasi, dan langkah perbaikan."></textarea></label>${key==='logs'?`<label>Skor performa demo (bukan nilai akhir RPS)<select name="score"><option value="0">0 — Tidak ada bukti</option><option value="1">1 — Belum kompeten</option><option value="2">2 — Berkembang</option><option value="3">3 — Baik</option><option value="4">4 — Sangat baik</option></select></label><label>Hasil penilaian<select name="outcome"><option>Perlu perbaikan</option><option>Kompeten dalam supervisi</option><option>Tidak dapat dinilai</option></select></label>`:''}<div class="actions"><button name="decision" value="Perlu revisi" class="btn light">Minta revisi</button><button name="decision" value="Terverifikasi" class="btn">Verifikasi demo</button></div></form>`}
function drawSkills(){let q=$('#skillSearch').value.toLowerCase();$('#skillList').innerHTML=DATA.competencies.filter(c=>(c.name+' '+c.group+' '+c.id).toLowerCase().includes(q)).map(c=>`<button type="button" class="row ${selected===c.id?'selected':''}" data-skill="${c.id}"><small>${c.id} · ${esc(c.group)}</small>${esc(c.name)}</button>`).join('')||'<p>Tidak ada target yang cocok.</p>';$('#chosenSkill').textContent=DATA.competencies.find(c=>c.id===selected).name;$('#skillList').querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{selected=b.dataset.skill;drawSkills()})}
function drawDx(){let q=$('#dxSearch').value.toLowerCase(),ger=$('#dxFilter').value==='gerontik';let list=DATA.catalog.diagnoses.filter(c=>(c.kode+' '+c.nama).toLowerCase().includes(q)&&(!ger||/jatuh|kulit|tekan|nutrisi|tidur|nyeri|mobilitas|memori|konfusi|perawatan diri|kesepian|isolasi sosial|eliminasi|inkontinensia|konstipasi|menelan/.test(c.nama.toLowerCase())));$('#dxCount').textContent=list.length+' diagnosis ditemukan';$('#dxList').innerHTML=list.map(c=>`<button class="row ${dx===c.kode?'selected':''}" data-dx="${c.kode}"><small>${c.kode} · ${esc(c.subkategori)}</small>${esc(c.nama)}</button>`).join('')||'<p>Tidak ada diagnosis yang cocok.</p>';let c=DATA.catalog.diagnoses.find(c=>c.kode===dx);$('#dxDetail').innerHTML=`<span class="eyebrow">${c.kode} · ${esc(c.jenis)}</span><h2>${esc(c.nama)}</h2><p class="tiny">Sumber sekunder · belum disahkan terhadap edisi resmi prodi</p><h3>Luaran yang tercantum pada sumber</h3>${pairs(c.slki)}<h3>Intervensi yang tercantum pada sumber</h3>${pairs(c.siki)}<div class="banner">Pasangan dengan tanda konflik belum boleh dipakai sebagai acuan kode final. Ketiadaan tanda konflik tidak berarti sudah tervalidasi resmi.</div><a href="${esc(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">Telaah halaman sumber ↗</a>`;$('#dxList').querySelectorAll('[data-dx]').forEach(b=>b.onclick=()=>{dx=b.dataset.dx;drawDx()})}
function pairs(a){return a.map(p=>`<div class="record"><strong>${esc(p.kode)} · ${esc(p.nama)}</strong>${p.conflictReason?`<p class="tiny"><span class="tag amber">Perlu verifikasi kode</span><br>${esc(p.conflictReason)}</p>`:''}</div>`).join('')||'<p>Belum tersedia pada snapshot sumber.</p>'}
function drawSop(){let q=$('#sopSearch').value.toLowerCase(),all=$('#sopFilter').value==='all';let list=DATA.sops.filter(s=>(all||s.priority)&&s.nama.toLowerCase().includes(q));$('#sopList').innerHTML=list.map(s=>`<article class="card"><span class="tag ${s.priority?'':'gray'}">${s.priority?'Prioritas lansia / dewasa':'Katalog sumber'}</span><h3>${esc(s.nama)}</h3><p>Pelajari sumber lengkap dan diskusikan kesesuaiannya dengan pembimbing.</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Baca di perawat.org ↗</a></article>`).join('')||'<p>Tidak ada SOP yang cocok.</p>'}
function download(name,text,type){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
 if(page==='sop'){$('#sopSearch').oninput=drawSop;$('#sopFilter').onchange=drawSop;drawSop()}
 if(page==='catalog'){$('#dxSearch').oninput=drawDx;$('#dxFilter').onchange=drawDx;drawDx()}
 document.querySelectorAll('[data-video]').forEach(b=>b.onclick=()=>{let f=document.createElement('iframe');f.src='https://www.youtube-nocookie.com/embed/'+b.dataset.video;f.title='Video pembelajaran Amzal Mortin Andas';f.allow='encrypted-media; picture-in-picture; fullscreen';f.allowFullscreen=true;f.referrerPolicy='strict-origin-when-cross-origin';b.replaceWith(f)});
 if(page==='logbook'){drawSkills();$('#skillSearch').oninput=drawSkills;$('#logForm').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target)),intent=e.submitter?.value||'draft';if(v.date>today())return toast('Tanggal kegiatan tidak boleh di masa depan.');if(v.context==='Praktik klinik'&&v.action==='Melakukan simulasi')return toast('Sesuaikan konteks menjadi Simulasi untuk kegiatan simulasi.');if(v.context==='Simulasi'&&v.action==='Melakukan dengan supervisi')return toast('Pilih Melakukan simulasi untuk konteks simulasi.');let old=db.logs.find(x=>x.id===editing);if(old&&!['Draf','Perlu revisi'].includes(old.status))return toast('Catatan ini sedang dinilai atau sudah terverifikasi.');let x={...(old||{}),...v,id:old?.id||uid(),skill:selected,status:intent==='submit'?'Diajukan':'Draf',updated:new Date().toISOString()};if(old){x.history=[...(old.history||[]),{...old,history:undefined}];db.logs[db.logs.indexOf(old)]=x}else db.logs.push(x);save();editing=null;render();toast('Catatan demo tersimpan.');};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{let x=db.logs.find(x=>x.id===b.dataset.edit);editing=x.id;selected=x.skill;drawSkills();for(let [k,v]of Object.entries(x)){let el=$('#logForm').elements.namedItem(k);if(el)el.value=v}$('#logForm').scrollIntoView({behavior:'smooth'});toast('Revisi dibuka; simpan atau ajukan kembali.');})}
 if(page==='reflection')$('#reflectionForm').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(db.reflections.some(x=>x.week===v.week))return toast('Minggu ini sudah memiliki refleksi. Gunakan tindak lanjut bila diminta revisi.');db.reflections.push({...v,id:uid(),status:'Diajukan',date:today()});save();render();toast('Refleksi diajukan untuk review demo.');};
 if(page==='attendance')$('#attendanceForm').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target)),d=new Date(v.date+'T12:00:00');if(v.date>today())return toast('Tanggal tidak boleh di masa depan.');if([0,6].includes(d.getDay()))return toast('Bawaan periode hanya Senin–Jumat. Hari pengganti memerlukan pengaturan koordinator.');if(db.attendance.some(x=>x.date===v.date&&x.shift===v.shift))return toast('Tanggal dan shift ini sudah dilaporkan.');if(v.presence==='Hadir'&&(!v.start||!v.end||v.end<=v.start))return toast('Isi jam masuk dan keluar yang berurutan.');if(v.presence!=='Hadir'&&!v.note.trim())return toast('Isi alasan izin atau sakit.');db.attendance.push({...v,id:uid(),status:'Diajukan',late:v.date<today(),created:new Date().toISOString()});save();render();toast('Laporan dinas diajukan untuk validasi demo.');};
 if(page==='skin')$('#skinForm').onsubmit=e=>{e.preventDefault();db.skin.push({...Object.fromEntries(new FormData(e.target)),id:uid(),status:'Draf'});save();render();toast('Contoh pengkajian tersimpan di browser.');};
 document.querySelectorAll('.resubmitForm').forEach(f=>f.onsubmit=e=>{e.preventDefault();let x=db[f.dataset.key].find(x=>x.id===f.dataset.id);x.corrections=[...(x.corrections||[]),{text:new FormData(f).get('correction'),at:new Date().toISOString()}];x.note=(x.note||x.plan||'')+'\nKoreksi: '+new FormData(f).get('correction');x.status='Diajukan';save();render();toast('Koreksi diajukan kembali.');});
 document.querySelectorAll('.reviewForm').forEach(f=>f.onsubmit=e=>{e.preventDefault();if(!teacher())return;let x=db[f.dataset.key].find(x=>x.id===f.dataset.id),v=Object.fromEntries(new FormData(f)),status=e.submitter.value;if(f.dataset.key==='logs'&&status==='Terverifikasi'&&v.outcome==='Kompeten dalam supervisi'&&(+v.score<3||x.action==='Mengamati'))return toast('Kompeten memerlukan bukti melakukan dan skor minimal 3 pada demo.');let r={status,comment:v.comment,at:new Date().toISOString(),...(f.dataset.key==='logs'?{score:+v.score,outcome:v.outcome}:{})};x.reviews=[...(x.reviews||[]),r];x.status=status;if(f.dataset.key==='logs')x.outcome=v.outcome;save();render();toast('Review demo tersimpan.');});
 if(page==='matrix'){$('#exportJson').onclick=()=>download('Data_Demo_Gerontik.json',JSON.stringify({preview:true,exportedAt:new Date().toISOString(),...db},null,2),'application/json');$('#exportCsv').onclick=()=>{let fields=['id','skill','date','shift','room','context','action','supervisor','summary','reflection','status','outcome'];const cell=v=>'"'+String(v??'').replace(/^(\s*[=+@-])/,"'$&").replace(/"/g,'""')+'"';download('Logbook_Demo_Gerontik.csv','\ufeff'+[fields,...db.logs.map(x=>fields.map(k=>x[k]))].map(a=>a.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')};$('#print').onclick=()=>window.print();$('#reset').onclick=()=>{if(confirm('Hapus seluruh catatan demo pada browser ini? Data aplikasi asli tidak terpengaruh.')){db=empty();save();render();toast('Data demo dihapus.')}}}
}
