function nl2br(value){return esc(value||'-').replace(/\n/g,'<br>')}
function initClinical(){if(!db.clinicalState)db.clinicalState={mahasiswa:{nama:'',nim:'',status:'Profesi Ners',kelas:'',pembimbing:''},demografi:{1:{},2:{}},instrumen:{1:{},2:{}},instrumenRaw:{1:{},2:{}},instrumentSchemaVersion:6,asuhan:{1:{},2:{}},h2t:{1:{},2:{}}};return db.clinicalState}
