const BAND=(min,max,range,label,level='neutral')=>({min,max,range,label,level});
const GUIDE={
 barthel:{range:'0–100',bands:[BAND(0,20,'0–20','Ketergantungan total','high'),BAND(21,60,'21–60','Ketergantungan berat','high'),BAND(61,90,'61–90','Ketergantungan sedang','review'),BAND(91,99,'91–99','Ketergantungan ringan','review'),BAND(100,100,'100','Mandiri pada ADL yang dinilai','low')],note:'Versi Barthel 100 poin. Klasifikasi fungsional yang dipakai aplikasi; bukan skor Barthel versi 20 poin. Tinjau aktivitas yang masih memerlukan bantuan.',source:'https://halofisioterapi.com/wp-content/uploads/2023/10/barthel-index-halofisio.pdf'},
 lawton:{range:'0–8',bands:[BAND(0,0,'0','Memerlukan bantuan pada seluruh 8 domain yang dinilai','review'),BAND(1,7,'1–7','Memerlukan bantuan pada sebagian domain IADL','review'),BAND(8,8,'8','Mandiri pada seluruh 8 domain yang dinilai','low')],note:'Kategori deskriptif dari jumlah domain mandiri, bukan derajat klinis ringan–berat. Di panti, tugas yang tidak diberi kesempatan tidak otomatis berarti tidak mampu; dokumentasikan konteks penilaian.',source:'https://hign.org/consultgeri/try-this-series/lawton-instrumental-activities-daily-living-iadl-scale'},
 mna_sf:{range:'0–14',bands:[BAND(0,7,'0–7','Malnutrisi menurut skrining MNA-SF','high'),BAND(8,11,'8–11','Berisiko malnutrisi','review'),BAND(12,14,'12–14','Status nutrisi normal menurut skrining','low')],note:'Hasil skrining membantu penilaian nutrisi lanjutan; gunakan versi MNA-SF yang sesuai.',source:'https://www.mna-elderly.com/sites/default/files/2021-10/MNA-indonesian.pdf'},
 frail:{range:'0–5',bands:[BAND(0,0,'0','Robust / tidak rapuh pada skrining','low'),BAND(1,2,'1–2','Pre-frail / pra-rapuh','review'),BAND(3,5,'3–5','Frail / rapuh','high')],note:'Tinjau komponen yang positif dan dampaknya pada aktivitas lansia.',source:'https://www.slu.edu/medicine/internal-medicine/geriatric-medicine/aging-successfully/-pdf/rapid-geriatric-assessment.pdf'},
 sarcf:{range:'0–10',bands:[BAND(0,3,'0–3','Skrining SARC-F negatif','low'),BAND(4,10,'4–10','Skrining positif / risiko sarkopenia','review')],note:'Skrining negatif tidak menyingkirkan seluruh masalah otot; hasil positif bukan diagnosis sarkopenia.',source:'https://www.slu.edu/medicine/internal-medicine/geriatric-medicine/aging-successfully/-pdf/rapid-geriatric-assessment.pdf'},
 tug:{range:'Waktu aktual (detik)',bands:[BAND(0,11.999999,'<12 detik','Di bawah ambang peningkatan risiko jatuh STEADI','low'),BAND(12,Infinity,'≥12 detik','Peningkatan risiko jatuh pada skrining','review')],note:'Catat alat bantu dan pengawasan. Waktu <12 detik tidak meniadakan risiko jatuh dari faktor lain. Jangan memaksakan tes bila tidak aman.',source:'https://www.cdc.gov/steadi/media/pdfs/STEADI-Assessment-TUG-508.pdf'},
 amt:{range:'0–10',bands:[BAND(0,3,'0–3','Gangguan ingatan berat menurut kategori AMT','high'),BAND(4,7,'4–7','Gangguan ingatan sedang menurut kategori AMT','review'),BAND(8,10,'8–10','Dalam rentang normal menurut AMT','low')],note:'Pertimbangkan bahasa, pendengaran, pendidikan dan perubahan dari kondisi dasar. Skrining bukan diagnosis demensia.',source:'https://kesprimkom.kemkes.go.id/assets/uploads/contents/others/2023kepmenkes2015.pdf'},
 gds:{range:'0–15',bands:[BAND(0,4,'0–4','Normal / skrining gejala depresi negatif','low'),BAND(5,8,'5–8','Gejala depresi ringan','review'),BAND(9,11,'9–11','Gejala depresi sedang','high'),BAND(12,15,'12–15','Gejala depresi berat','high')],note:'Kategori GDS-15 mengacu HIGN. Ini tingkat gejala pada skrining, bukan diagnosis pasti. GDS tidak menilai risiko bunuh diri; kekhawatiran keselamatan perlu dilaporkan terlepas dari skor.',source:'https://hign.org/consultgeri/try-this-series/geriatric-depression-scale-gds'},
 whoqol:{range:'Total 24–120; setiap facet 4–20',profile:'whoqol',note:'Rujukan yang digunakan tidak menetapkan batas klinis universal rendah/sedang/tinggi. Kategori di sini adalah profil respons, bukan cutoff total. Fokus pada facet dan butir dengan skor setelah pembalikan 1–2, serta prioritas yang disampaikan lansia.',source:'https://mji.ui.ac.id/journal/index.php/mji/article/download/5065/2108?inline=1'},
 loneliness:{range:'8–32',profile:'loneliness',note:'ULS-8 asli tidak menyediakan batas klinis ringan/sedang/berat yang digunakan pada preview ini. Profil menampilkan jumlah butir dengan skor setelah pembalikan 3–4, bukan ambang total diagnosis kesepian.',source:'https://pubmed.ncbi.nlm.nih.gov/3572711/'},
 gad7:{range:'0–21',bands:[BAND(0,4,'0–4','Gejala kecemasan minimal','low'),BAND(5,9,'5–9','Gejala kecemasan ringan','review'),BAND(10,14,'10–14','Gejala kecemasan sedang','high'),BAND(15,21,'15–21','Gejala kecemasan berat','high')],note:'Skor ≥10 merupakan penanda perlunya evaluasi lebih lanjut, bukan diagnosis otomatis.',source:'https://app.mhpss.net/?get=393/phq-9-and-gad-7-manual.pdf'},
 nrs:{range:'0–10',bands:[BAND(0,0,'0','Tidak nyeri','low'),BAND(1,3,'1–3','Nyeri ringan','review'),BAND(4,6,'4–6','Nyeri sedang','review'),BAND(7,10,'7–10','Nyeri berat','high')],note:'Kategori praktis intensitas nyeri; skema batas dapat berbeda antar pedoman. Tetap nilai lokasi, onset, dampak dan respons lansia. Nyeri baru yang mengkhawatirkan tidak menunggu skor tertentu.',source:'https://openstax.org/books/medical-surgical-nursing/pages/7-2-pain-assessment'},
 sleep:{range:'0–10',bands:[BAND(0,0,'0','Kualitas tidur sangat buruk','high'),BAND(1,3,'1–3','Kualitas tidur buruk','review'),BAND(4,6,'4–6','Kualitas tidur cukup','review'),BAND(7,9,'7–9','Kualitas tidur baik','low'),BAND(10,10,'10','Kualitas tidur sangat baik','low')],note:'Deskriptor SQS sesuai penelitian pengembangan. Kategori ini menggambarkan kualitas tidur yang dirasakan, bukan diagnosis insomnia.',source:'https://pmc.ncbi.nlm.nih.gov/articles/PMC6223557/'},
 dssi:{range:'11–33; interaksi 4–12; dukungan subjektif 7–21',profile:'dssi',note:'Kategori klinis universal rendah/sedang/tinggi tidak ditetapkan pada rujukan penskoran yang dipakai. Profil menandai respons skor 1 (tingkat dukungan terendah pada item), bukan cutoff total.',source:'https://alswh.org.au/wp-content/uploads/2020/08/DDSSection2.7DSSI.pdf'},
 mspss:{range:'Mean total 1–7 (jumlah mentah 12–84)',bands:[BAND(1,2.9,'1,0–2,9','Persepsi dukungan rendah','review'),BAND(3,5,'3,0–5,0','Persepsi dukungan sedang','review'),BAND(5.1,7,'5,1–7,0','Persepsi dukungan tinggi','low')],note:'Pengelompokan deskriptif yang disarankan Zimet, bukan norma populasi/cutoff klinis. Untuk menutup celah angka desimal, kategori memakai mean yang dibulatkan 1 desimal; mean asli tetap ditampilkan 2 desimal dan skor mentah tidak diubah.',source:'https://app.mhpss.net/?get=393/mspss_scoring.pdf'},
 fourat:{range:'0–12',bands:[BAND(0,0,'0','Delirium / gangguan kognitif berat kurang mungkin','low'),BAND(1,3,'1–3','Kemungkinan gangguan kognitif','review'),BAND(4,12,'4–12','Kemungkinan delirium ± gangguan kognitif','prompt')],note:'Skor ≥4 perlu penilaian klinis segera oleh petugas berwenang. Skor rendah tidak menyingkirkan delirium bila terdapat perubahan akut atau informasi belum lengkap.',source:'https://www.the4at.com/userguide'},
 sppb:{range:'0–12',bands:[BAND(0,9,'0–9','Mobilitas terbatas','review'),BAND(10,12,'10–12','Mobilitas dalam rentang normal menurut SPPB','low')],note:'Kategori mengikuti KMK 2015/2023. Tinjau keseimbangan, kecepatan berjalan dan chair stand secara terpisah; skor ini tidak menjamin bebas risiko jatuh.',source:'https://kesprimkom.kemkes.go.id/assets/uploads/contents/others/2023kepmenkes2015.pdf'}
};
const PRE_V5_INTERP=Object.fromEntries(Object.entries(INSTRUMEN).map(([k,v])=>[k,v.interp]));
function bandValue(k,total){return k==='mspss'?Math.round(total/12*10)/10:total}
function matchBand(k,total){let g=GUIDE[k],value=bandValue(k,total);return g.bands?.find(b=>value>=b.min&&value<=b.max)}
for(const[k,g]of Object.entries(GUIDE)){INSTRUMEN[k].interp=total=>{let b=matchBand(k,total);return b?{t:b.label+' ('+b.range+')',c:b.level==='low'?'normal':b.level==='review'?'mild':'severe'}:{t:'Skor '+total+'; interpretasi berbasis profil butir/domain, tanpa cutoff klinis total.',c:''}};}
function assessmentV5(k,week=clinicalWeek){const def=INSTRUMEN[k],g=GUIDE[k],a=State.instrumen[week]?.[k]||{},n=def.items.filter(i=>a[i.id]!==undefined&&a[i.id]!=='').length,total=def.items.reduce((s,i)=>s+(Number(a[i.id])||0),0),complete=n===def.items.length;let result={n,total,count:def.items.length,complete,category:n?'Belum lengkap — kategori belum ditetapkan':'Belum diisi',range:'—',level:'neutral',detail:'',note:g.note};if(!complete)return result;let b=matchBand(k,total);if(b)return {...result,category:b.label,range:b.range,level:b.level,detail:k==='mspss'?'Mean kategori (1 desimal): '+bandValue(k,total).toFixed(1):''};
let picked=def.items.filter(i=>k==='whoqol'?Number(a[i.id])<=2:k==='loneliness'?Number(a[i.id])>=3:Number(a[i.id])===1);return {...result,category:picked.length?'Ada respons yang perlu ditelaah':'Tidak ada respons pada tingkat yang ditandai',range:g.range,level:picked.length?'review':'neutral',detail:(k==='whoqol'?'Butir dengan skor 1–2 setelah pembalikan: ':k==='loneliness'?'Butir dengan skor 3–4 setelah pembalikan: ':'Butir dengan skor dukungan terendah (1): ')+picked.length+'/'+def.items.length+(picked.length?' — nomor '+picked.map(i=>def.items.indexOf(i)+1).join(', '):'')+'. Ini profil respons, bukan klasifikasi klinis total.'};}
function interpretationRows(k,current,forPdf=false){let g=GUIDE[k];if(!g.bands)return `<tr><td>${esc(g.range)}</td><td>Profil respons / telaah domain; tidak diberi kategori klinis berdasarkan total.</td></tr>`;return g.bands.map(b=>`<tr ${current?.complete&&current.range===b.range&&!forPdf?'class="current-band" aria-current="true"':''}><td>${esc(b.range)}</td><td>${esc(b.label)}${current?.complete&&current.range===b.range?' — hasil saat ini':''}</td></tr>`).join('')}
function guidePanel(k){let r=assessmentV5(k),g=GUIDE[k];return `<section class="interpretation-guide"><h3>Panduan kategori & rentang skor</h3>${r.complete?`<div class="result-label result-${r.level}">Skor ${esc(formatInstrumentDisplayScore(INSTRUMEN[k],r.total))} · ${esc(r.category)}</div>`:`<p class="tiny">${r.n}/${r.count} butir terisi — ${esc(r.category)}</p>`}<p class="tiny">Rentang instrumen: ${esc(g.range)}. Kategori baru ditentukan setelah seluruh butir terisi.</p><div class="scroll"><table><thead><tr><th>Rentang skor</th><th>Kategori / makna</th></tr></thead><tbody>${interpretationRows(k,r)}</tbody></table></div><p class="tiny">${esc(g.note)}</p><a class="tiny" href="${esc(g.source)}" target="_blank" rel="noopener noreferrer">Lihat rujukan interpretasi ↗</a></section>`}
const oldInstScoreV5=instScore;instScore=function(k,w=clinicalWeek){let s=oldInstScoreV5(k,w),r=assessmentV5(k,w);return {...s,interpretation:r.complete?r.category+' ('+r.range+')':r.category,assessment:r}};
function scoreHTMLV5(k){let s=instScore(k),r=s.assessment;return `<div class="result-head"><span class="eyebrow">Hasil saat ini</span><strong>${s.n?esc(s.shown):'—'}</strong></div><span class="result-label result-${r.level}">${esc(r.category)}</span><p>${s.n}/${s.count} butir${r.complete?' · rentang kategori: '+esc(r.range):''}</p>${r.detail?`<p>${esc(r.detail)}</p>`:''}${s.detail?`<p>${esc(s.detail)}</p>`:''}<p class="tiny">${esc(r.complete?r.note:'Lengkapi butir sebelum menggunakan hasil. Jawaban kosong tidak dihitung sebagai tidak bermasalah.')}</p>`}
const oldUpdateScoreV5=updateScorePanel;updateScorePanel=function(){oldUpdateScoreV5();if($('#clinicalScore'))$('#clinicalScore').innerHTML=scoreHTMLV5(clinicalInstrument);let g=$('#guideV5');if(g)g.innerHTML=guidePanel(clinicalInstrument);};
const oldFullReportV5=fullReportHTML;fullReportHTML=function(){oldFullReportV5();let root=$('#printReport');for(let w of [1,2]){let section=root.querySelectorAll('.report-week')[w-1],filled=Object.keys(INSTRUMEN).filter(k=>assessmentV5(k,w).n>0),scores=section.querySelectorAll('.report-score');filled.forEach((k,i)=>{let r=assessmentV5(k,w),s=instScore(k,w),target=scores[i];if(!target)return;target.textContent='Skor / kategori: '+s.shown+' — '+r.category+(r.complete?' ('+r.range+')':'');target.insertAdjacentHTML('afterend',`<div class="report-box"><strong>Interpretasi & fokus telaah</strong>\n${esc(r.detail||'')}\n${esc(r.note)}</div><table class="report-table"><thead><tr><th style="width:28%">Rentang skor</th><th style="width:72%">Kategori / makna</th></tr></thead><tbody>${interpretationRows(k,r,true)}</tbody></table><p class="report-note">Rujukan interpretasi: ${esc(GUIDE[k].source)}</p>`);});section.querySelectorAll('.report-plan').forEach((el,i)=>{let p=State.asuhan[w]?.rencana?.[i];if(!p)return;let anchor=el.querySelectorAll('p')[1];anchor?.insertAdjacentHTML('afterend',`<p><strong>Luaran SLKI — isian mahasiswa:</strong><br>${nl2br(p.slkiManual||'[belum diisi]')}</p><p><strong>Intervensi SIKI — isian mahasiswa:</strong><br>${nl2br(p.sikiManual||'[belum diisi]')}</p>`);});section.insertAdjacentHTML('beforeend',summaryTableV5(w,true));}
return root.innerHTML;};
const oldPdfDefinitionV5=geroPdfDefinition;geroPdfDefinition=function(root,info={}){let d=oldPdfDefinitionV5(root,info);d.defaultStyle.alignment='justify';d.styles.h2.alignment='left';d.styles.h3.alignment='left';d.styles.note.alignment='justify';const walk=v=>{if(!v||typeof v!=='object')return;if(v.table&&v.table.body.length<=6&&JSON.stringify(v.table.body[0]).includes('Rentang skor'))v.unbreakable=true;if(v.table)for(const row of v.table.body)for(const c of row)if(c&&Object.keys(c).length)c.alignment='left';for(const x of Object.values(v))if(Array.isArray(x))x.forEach(walk);else if(x&&typeof x==='object')walk(x);};walk(d.content);return d;};
function summaryTableV5(w,report=false){return `<h3>Ringkasan interpretasi — Minggu ${w}</h3><p class="${report?'report-note':'tiny'}">Fokus telaah bukan urutan kegawatan otomatis. Jangan membandingkan skor mentah antar instrumen. Tentukan prioritas bersama pembimbing dari kondisi, perubahan akut dan kebutuhan lansia.</p><div class="scroll"><table class="${report?'report-table':''}"><thead><tr><th>Instrumen</th><th>Skor</th><th>Kategori / profil</th><th>Fokus telaah</th></tr></thead><tbody>${Object.keys(INSTRUMEN).map(k=>{let r=assessmentV5(k,w),s=instScore(k,w);return `<tr><td>${esc(INSTRUMEN[k].title)}</td><td>${r.n?esc(s.shown):'—'}<br>${r.n}/${r.count} butir</td><td>${esc(r.category)}${r.complete?'<br>'+esc(r.range):''}</td><td>${r.complete?(r.level==='prompt'?'Perlu penilaian klinis segera':r.level==='high'?'Bahas temuan bermakna dengan pembimbing':r.level==='review'?'Telaah lanjut sesuai domain':'Tinjau bersama konteks klinis'):'Lengkapi / tentukan kebutuhan pemeriksaan'}</td></tr>`}).join('')}</tbody></table></div>`}
views.interpretation=()=>pageTitle('Skor → kategori → telaah klinis','Ringkasan hasil instrumen.','Lihat hasil masing-masing instrumen pada minggu yang dipilih. Rentang dan jenis kategorinya tetap mengikuti rujukan masing-masing alat.')+clinicalToolbar()+`<div class="card section">${summaryTableV5(clinicalWeek)}</div>`;
function enhanceV5(){if(page==='instruments'){
 const source=$('#app .source-note');if(source&&!$('#guideV5'))source.insertAdjacentHTML('afterend','<div id="guideV5">'+guidePanel(clinicalInstrument)+'</div>');if($('#clinicalScore'))$('#clinicalScore').innerHTML=scoreHTMLV5(clinicalInstrument);
 const sub=$('#app > .sub');if(sub)sub.textContent='Pertanyaan, pilihan jawaban, bobot dan perhitungan skor asli dipertahankan. Interpretasi kini dilengkapi kategori, rentang dan rujukan agar lebih mudah ditelaah.';
 }
 if(page==='careplan'){
  document.querySelectorAll('.removable').forEach(el=>{let target=el.querySelector('[data-plan]');if(!target)return;let i=+target.dataset.plan,p=State.asuhan[clinicalWeek].rencana[i],heading=el.querySelector('h3');if(heading&&!el.querySelector('[data-key="slkiManual"]'))heading.insertAdjacentHTML('afterend',`<div class="manual-plan"><p class="tiny">Tulis luaran dan intervensi berdasarkan hasil pengkajian serta arahan pembimbing. Pilihan katalog di bawah hanya referensi.</p>${inputArea('Luaran keperawatan (SLKI) — isian mahasiswa',p.slkiManual,`data-plan="${i}" data-key="slkiManual"`)}${inputArea('Intervensi keperawatan (SIKI) — isian mahasiswa',p.sikiManual,`data-plan="${i}" data-key="sikiManual"`)}</div>`);el.querySelectorAll('[data-key="slkiManual"],[data-key="sikiManual"]').forEach(e=>e.oninput=()=>{p[e.dataset.key]=e.value;clinicalSave()});
  });let sel=$('#newDx');if(sel){sel.onchange=()=>{let code=sel.value;if(!code)return;let a=State.asuhan[clinicalWeek]||{};if((a.rencana||[]).some(p=>p.kode===code)){toast('Diagnosis ini sudah memiliki rencana. Isi atau revisi kolom di bawah.');return;}$('#addPlan').click();};}let add=$('#addPlan');if(add)add.hidden=true;
 }
}
