// V6: formative competency assessment, role-specific dashboards, interface review.
function competencyRecords(){if(!Array.isArray(db.competency))db.competency=[];return db.competency}
let competencyEditing=null;
const RUBRICS={
 DOPS:{name:'DOPS · keterampilan prosedural',items:[['Indikasi, kontraindikasi dan risiko',true],['Persiapan alat, lingkungan, lansia dan persetujuan',true],['Kebersihan tangan dan APD sesuai kebutuhan',true],['Langkah tindakan sesuai SOP dan supervisi',false],['Keselamatan, kenyamanan, privasi dan martabat',true],['Pemantauan respons, penghentian dan eskalasi',true],['Dokumentasi objektif tindakan dan hasil',false]]},
 'mini-CEX':{name:'mini-CEX / BST · pengkajian klinik',items:[['Identifikasi, persetujuan dan penjelasan',true],['Komunikasi terapeutik sesuai kebutuhan sensorik dan budaya',false],['Pengkajian terarah dan pemeriksaan',false],['Interpretasi temuan dan prioritas masalah',false],['Keselamatan, pencegahan infeksi dan privasi',true],['Intervensi sesuai kompetensi dan respons lansia',true],['Kolaborasi, komunikasi dan dokumentasi',false]]},
 EBN:{name:'Telaah EBN · journal reading (adaptasi)',items:[['Rumusan pertanyaan klinik / PICO',false],['Strategi pencarian dan pemilihan sumber',false],['Telaah kritis metode dan hasil',false],['Kesesuaian bukti untuk lansia di panti',false],['Pertimbangan keselamatan, etik dan preferensi lansia',true],['Rencana penerapan, evaluasi dan penyampaian',false]]}
};
const COMP_SCALE=['0 — Belum ada bukti','1 — Memerlukan arahan penuh','2 — Memerlukan banyak arahan','3 — Memadai dalam supervisi','4 — Konsisten dalam supervisi'];
function competencyName(x){return DATA.competencies.find(c=>c.id===x.skill)?.name||x.skill}
function competencyError(v,submit){if(v.date&&(!/^\d{4}-\d{2}-\d{2}$/.test(v.date)||Number.isNaN(Date.parse(v.date+'T12:00:00'))||v.date>today()))return 'Tanggal kegiatan harus valid dan tidak di masa depan.';if(!DATA.competencies.some(c=>c.id===v.skill)||!RUBRICS[v.method])return 'Pilih kompetensi dan metode penilaian.';if(v.context==='Praktik klinik'&&v.action==='Melakukan simulasi'||v.context==='Simulasi'&&v.action==='Melakukan dengan supervisi')return 'Sesuaikan peran mahasiswa dengan konteks praktik atau simulasi.';if(submit){for(let k of ['date','shift','room','week','supervisor','summary','evidence','reflection'])if(!String(v[k]||'').trim())return 'Lengkapi tanggal, shift, wisma, minggu, pembimbing, tindakan, bukti dan refleksi sebelum diajukan.';}return '';}
function assessmentError(x,r,decision){if(!r.examiner?.trim()||!r.comment?.trim()||!r.observed?.trim())return 'Isi nama penilai, tanggal observasi dan umpan balik.';if(r.observed<x.date||r.observed>today())return 'Tanggal observasi harus antara tanggal kegiatan dan hari ini.';if(decision==='Perlu revisi')return '';let items=RUBRICS[x.method].items;if(!Array.isArray(r.scores)||r.scores.length!==items.length||r.scores.some(s=>s===''||!(s==='NA'||Number.isInteger(+s)&&+s>=0&&+s<=4)))return 'Nilai setiap aspek; pilih N/A bila tidak relevan.';if(r.scores.includes('NA')&&!r.naReason?.trim())return 'Jelaskan alasan aspek N/A; aspek tersebut dikeluarkan dari penyebut.';let valid=r.scores.filter(s=>s!=='NA');if(!valid.length)return 'Seluruh aspek N/A tidak dapat menghasilkan nilai. Kembalikan untuk dilengkapi.';if(!['Kompeten dalam supervisi','Perlu perbaikan','Tidak dapat dinilai'].includes(r.outcome))return 'Pilih hasil penilaian.';if(r.outcome==='Kompeten dalam supervisi'){if(x.action==='Mengamati')return 'Pengamatan saja belum membuktikan kemampuan melakukan.';if(r.scores.some((s,i)=>items[i][1]&&(s==='NA'||+s<3)))return 'Aspek keselamatan wajib terobservasi dengan skor minimal 3 pada aturan formatif preview.';if(valid.some(s=>+s<3))return 'Masih ada aspek di bawah 3; pilih perlu perbaikan atau lakukan observasi ulang.';}return '';}
function competencyScore(scores){let a=scores.filter(s=>s!==''&&s!=='NA');return a.length?Math.round(a.reduce((n,s)=>n+Number(s),0)/(4*a.length)*1000)/10:null;}
function latestCompetencies(context){let map=new Map();for(let x of competencyRecords().filter(x=>x.context===context))map.set(x.skill,x);return [...map.values()];}
function passedCompetencies(context){return latestCompetencies(context).filter(x=>x.status==='Terverifikasi'&&x.reviews?.at(-1)?.outcome==='Kompeten dalam supervisi'&&x.action!=='Mengamati');}
function compSelect(name,label,values,value){return `<label>${label}<select name="${name}">${values.map(v=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function competencyForm(){let x=competencyRecords().find(x=>x.id===competencyEditing&&['Draf','Perlu revisi'].includes(x.status))||{date:today(),shift:'Pagi',room:'Wisma A',week:'1',context:'Praktik klinik',action:'Melakukan dengan supervisi',method:'DOPS',skill:DATA.competencies[0].id};return `<div class="card"><div class="section-head"><h2>${x.id?'Revisi / lanjutkan draf':'Catat kompetensi praktik'}</h2><span class="tag">Mahasiswa</span></div><p>Catat tindakan yang benar-benar dilakukan, gunakan kode kasus anonim, lalu ajukan observasi kepada pembimbing.</p><form id="competencyForm" novalidate><label>Kompetensi<select name="skill">${DATA.competencies.map(c=>`<option value="${c.id}" ${c.id===x.skill?'selected':''}>${c.id} · ${esc(c.name)}</option>`).join('')}</select></label><div class="fields"><label>Tanggal kegiatan<input type="date" name="date" max="${today()}" value="${esc(x.date)}"></label>${compSelect('week','Minggu',['1','2'],x.week)}${compSelect('shift','Shift',['Pagi','Siang'],x.shift)}${compSelect('room','Wisma',['Wisma A','Wisma B','Wisma C','Wisma D'],x.room)}${compSelect('context','Konteks',['Praktik klinik','Simulasi'],x.context)}${compSelect('action','Peran mahasiswa',['Melakukan dengan supervisi','Melakukan simulasi','Mengamati'],x.action)}${compSelect('method','Metode observasi',Object.keys(RUBRICS),x.method)}<label>Nama pembimbing<input name="supervisor" maxlength="120" value="${esc(x.supervisor)}"></label></div><p class="tiny">DOPS untuk prosedur; mini-CEX/BST untuk pengkajian; EBN untuk journal reading. Penentuan akhir mengikuti pembimbing.</p><label>Kode kasus anonim (opsional)<input name="caseCode" maxlength="40" value="${esc(x.caseCode)}" placeholder="Contoh: L-01 · tanpa nama / nomor rekam medis"></label>${[['summary','Tindakan, respons lansia dan hasil'],['evidence','Bukti observasi / rujukan portofolio anonim'],['reflection','Refleksi dan rencana perbaikan']].map(([k,l])=>`<label>${l}<textarea name="${k}" maxlength="5000">${esc(x[k])}</textarea></label>`).join('')}<div class="actions"><button class="btn light" name="intent" value="draft">Simpan draf</button><button class="btn" name="intent" value="submit">Ajukan penilaian dosen →</button>${x.id?'<button type="button" class="btn light" id="cancelCompetency">Batal revisi</button>':''}</div><p id="competencyError" role="alert" class="form-error"></p></form></div>`;}
function competencyReviewForm(x){let rubric=RUBRICS[x.method];return `<form class="competencyReview" data-id="${x.id}" novalidate><h3>Observasi dosen · ${esc(rubric.name)}</h3><p class="tiny">Rubrik formatif 0–4 dari draf RPS; EBN merupakan adaptasi. N/A tidak dihitung dalam penyebut. Aspek bertanda * wajib terobservasi untuk hasil kompeten.</p><div class="fields"><label>Nama dosen / preseptor penilai<input name="examiner" maxlength="120"></label><label>Tanggal observasi<input type="date" name="observed" min="${esc(x.date)}" max="${today()}" value="${esc(x.date)}"></label></div>${rubric.items.map(([t,critical],i)=>`<label>${i+1}. ${esc(t)}${critical?' *':''}<select name="criterion${i}" data-score><option value="">Pilih hasil observasi</option>${COMP_SCALE.map((t,j)=>`<option value="${j}">${t}</option>`).join('')}<option value="NA">N/A — Tidak relevan / tidak diobservasi</option></select></label>`).join('')}<p class="score-preview" aria-live="polite">Skor belum lengkap.</p><label>Alasan aspek N/A (wajib bila dipilih)<textarea name="naReason" maxlength="1500"></textarea></label><label>Hasil penilaian<select name="outcome"><option value="">Pilih keputusan dosen</option><option>Kompeten dalam supervisi</option><option>Perlu perbaikan</option><option>Tidak dapat dinilai</option></select></label><label>Umpan balik, bukti observasi dan tindak lanjut<textarea name="comment" maxlength="5000"></textarea></label><div class="banner tiny">Aturan formatif preview: hasil “kompeten” memerlukan semua aspek relevan ≥3 dan seluruh aspek keselamatan terobservasi ≥3. Keputusan tetap pada dosen. Belum menjadi nilai akhir atau standar kelulusan resmi prodi.</div><div class="actions"><button class="btn light" name="decision" value="Perlu revisi">Kembalikan untuk revisi</button><button class="btn" name="decision" value="Terverifikasi">Simpan hasil penilaian</button></div><p role="alert" class="form-error"></p></form>`;}
function competencyReviewHTML(x,r){return `<div class="banner"><strong>${esc(r.outcome||r.decision)}${r.percent!==null&&r.percent!==undefined?' · '+r.percent+'/100':''}</strong><p>${esc(r.comment)}</p><span class="tiny">${esc(r.examiner)} · Observasi ${esc(r.observed)} · Dicatat ${esc(r.at)}</span><details><summary>Rincian rubrik & N/A</summary>${r.scores?.map((s,i)=>`<p>${i+1}. ${esc(RUBRICS[r.method||x.method].items[i]?.[0])}: <strong>${s===''?'Belum dinilai':esc(s)}</strong></p>`).join('')||''}${r.naReason?`<p>Alasan N/A: ${esc(r.naReason)}</p>`:''}</details></div>`;}
function competencyList(){let a=competencyRecords().filter(x=>!teacher()||x.status!=='Draf');return a.length?a.slice().reverse().map(x=>`<article class="record"><div class="section-head">${badge(x.status)}<span class="tiny">Minggu ${esc(x.week)} · ${esc(x.date)} · ${esc(x.shift)} · ${esc(x.room)}</span></div><h3>${esc(x.skill)} · ${esc(competencyName(x))}</h3><p class="tiny">${esc(x.context)} · ${esc(x.action)} · ${esc(x.method)} · Pembimbing: ${esc(x.supervisor||'Belum diisi')}</p>${x.caseCode?`<p>Kode kasus: ${esc(x.caseCode)}</p>`:''}<p>${esc(x.summary||'Draf belum lengkap.')}</p><details><summary>Bukti, refleksi & riwayat</summary><p>Bukti: ${esc(x.evidence||'Belum diisi')}</p><p>Refleksi: ${esc(x.reflection||'Belum diisi')}</p><p class="tiny">${x.history?.length||0} versi sebelumnya disimpan dan ikut dicetak pada PDF lengkap.</p></details>${(x.reviews||[]).map(r=>competencyReviewHTML(x,r)).join('')}${!teacher()&&['Draf','Perlu revisi'].includes(x.status)?`<button class="btn light" data-comp-edit="${x.id}">Buka / perbaiki catatan</button>`:''}${teacher()&&x.status==='Diajukan'?competencyReviewForm(x):''}</article>`).join(''):'<div class="blank">Belum ada form kompetensi. Mahasiswa mengajukan bukti; dosen menilai setelah observasi.</div>';}
views.competency=()=>pageTitle('Portofolio · observasi · umpan balik','Form kompetensi gerontik.','Penilaian kompetensi tindakan di panti; simulasi dan praktik klinik ditampilkan terpisah.')+`<div class="banner">${teacher()?'Mode dosen: baca bukti mahasiswa dan nilai pengajuan di bawah.':'Alur: simpan draf → ajukan → observasi dosen → hasil / revisi.'} Ini simulasi lokal; nama penilai bukan tanda tangan elektronik.</div>${teacher()?'':competencyForm()}<div class="card section"><h2>${teacher()?'Pengajuan & hasil penilaian':'Riwayat kompetensi saya'}</h2>${competencyList()}</div>`;
function bindCompetency(){let f=$('#competencyForm');if(f)f.onsubmit=e=>{e.preventDefault();if(teacher())return;let v=Object.fromEntries(new FormData(f)),submit=e.submitter?.value==='submit',error=competencyError(v,submit),old=competencyRecords().find(x=>x.id===competencyEditing);if(old&&!['Draf','Perlu revisi'].includes(old.status))error='Catatan sedang dinilai atau sudah selesai; buat asesmen ulang baru.';if(error){$('#competencyError').textContent=error;return;}let x={...(old||{}),...v,id:old?.id||uid(),status:submit?'Diajukan':'Draf',updated:new Date().toISOString()};if(old){x.history=[...(old.history||[]),{...old,history:undefined}];db.competency[db.competency.indexOf(old)]=x;}else db.competency.push(x);if(!save())return;competencyEditing=null;render();toast(submit?'Form diajukan untuk penilaian dosen.':'Draf kompetensi tersimpan.');};$('#cancelCompetency')?.addEventListener('click',()=>{competencyEditing=null;render()});document.querySelectorAll('[data-comp-edit]').forEach(b=>b.onclick=()=>{competencyEditing=b.dataset.compEdit;render();$('#competencyForm').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('.competencyReview').forEach(f=>{f.querySelectorAll('[data-score]').forEach(el=>el.onchange=()=>{let s=[...f.querySelectorAll('[data-score]')].map(e=>e.value);f.querySelector('.score-preview').textContent=s.some(x=>x==='')?'Skor belum lengkap.':competencyScore(s)===null?'Seluruh aspek N/A.':`Skor formatif: ${competencyScore(s)}/100 · ${s.filter(x=>x!=='NA').length} aspek dihitung`;});f.onsubmit=e=>{e.preventDefault();if(!teacher())return;let x=competencyRecords().find(x=>x.id===f.dataset.id);if(x?.status!=='Diajukan')return;let r=Object.fromEntries(new FormData(f)),decision=e.submitter?.value,scores=[...f.querySelectorAll('[data-score]')].map(e=>e.value);r={method:x.method,examiner:r.examiner,observed:r.observed,comment:r.comment,naReason:r.naReason,outcome:r.outcome,scores,decision,at:new Date().toISOString()};let error=assessmentError(x,r,decision);if(error){f.querySelector('.form-error').textContent=error;return;}r.percent=decision==='Terverifikasi'?competencyScore(scores):null;x.reviews=[...(x.reviews||[]),r];x.status=decision;x.updated=r.at;if(!save())return;render();toast('Penilaian dan umpan balik tersimpan pada preview.');};});}
function dashboardStats(){let clinical=passedCompetencies('Praktik klinik').length,simulation=passedCompetencies('Simulasi').length,all=competencyRecords(),pending=all.filter(x=>x.status==='Diajukan').length;return {clinical,simulation,pending,revision:all.filter(x=>x.status==='Perlu revisi').length,all};}
views.dashboard=()=>{let s=dashboardStats(),queues=[['competency','Form kompetensi',s.pending],['review','Logbook',db.logs.filter(x=>x.status==='Diajukan').length],['review','Refleksi',db.reflections.filter(x=>x.status==='Diajukan').length],['review','Kehadiran',db.attendance.filter(x=>x.status==='Diajukan').length]],n=DATA.competencies.length,ratio=s.clinical/n, circumference=314.16;return pageTitle(teacher()?'Ruang pembimbing':'Perkembangan belajar',teacher()?'Dashboard dosen.':'Dashboard mahasiswa.',`Preview satu portofolio pada browser ini${State.mahasiswa.nama?' · '+State.mahasiswa.nama:''}. Data ditampilkan dari isian, belum tersinkron dengan akun mahasiswa sebenarnya.`)+`<div class="dash-stats">${(teacher()?[[queues.reduce((n,q)=>n+q[2],0),'Pengajuan menunggu review','blue'],[s.clinical,'Kompetensi klinik terverifikasi','cyan'],[s.revision,'Form perlu revisi','violet'],[s.simulation,'Kompetensi simulasi','indigo']]:[[s.clinical,'Kompetensi klinik terverifikasi','blue'],[s.pending,'Form menunggu dosen','cyan'],[s.revision,'Form perlu diperbaiki','violet'],[s.simulation,'Kompetensi simulasi','indigo']]).map(([v,t,c])=>`<div class="dash-stat ${c}"><span class="stat-icon" aria-hidden="true">${c==='blue'?'◇':c==='cyan'?'◷':c==='violet'?'↗':'▧'}</span><span class="tiny">${t}</span><strong>${v}</strong><span class="spark" aria-hidden="true"></span></div>`).join('')}</div><div class="dashboard-panels"><div class="card coverage"><span class="eyebrow">Cakupan kompetensi klinik</span><div class="ring-wrap"><svg viewBox="0 0 120 120" role="img" aria-label="${s.clinical} dari ${n} kompetensi klinik terverifikasi"><circle cx="60" cy="60" r="50" fill="none" stroke="#28375d" stroke-width="10"/><circle class="ring-progress" cx="60" cy="60" r="50" fill="none" stroke="#53d7f6" stroke-width="10" stroke-linecap="round" transform="rotate(-90 60 60)" stroke-dasharray="${circumference}" stroke-dashoffset="${circumference*(1-ratio)}"/><\/svg><div><strong>${s.clinical}<small>/${n}</small></strong><span>cakupan katalog</span></div></div><p>Asesmen terbaru per kompetensi, konteks klinik, hasil kompeten dalam supervisi. Katalog bukan target wajib atau nilai akhir.</p></div><div class="card"><div class="section-head"><h2>${teacher()?'Antrean penilaian':'Dokumen & umpan balik'}</h2><span class="tag">Langsung dari isian</span></div><div class="queue-chart">${queues.map(([p,t,n])=>`<button class="queue-row" data-go="${p}"><span>${t}</span><span class="queue-track"><i style="width:${n?Math.max(6,n/Math.max(1,...queues.map(x=>x[2]))*100):0}%"></i></span><strong>${n}</strong></button>`).join('')}</div><p class="tiny">Angka menunjukkan pengajuan berstatus Diajukan. Buka menu untuk melihat bukti dan riwayat revisi.</p><button class="btn" data-go="competency">${teacher()?'Buka penilaian kompetensi':'Isi form kompetensi'} →</button></div></div><div class="grid section">${[1,2].map(w=>{let complete=Object.keys(INSTRUMEN).filter(k=>assessmentV5(k,w).complete).length,started=MODULES.filter(m=>moduleCountForWeek(m,w)).length;return `<div class="card"><span class="eyebrow">Minggu ${w}</span><h3>${complete}/17 instrumen lengkap</h3><div class="meter"><i style="width:${complete/17*100}%"></i></div><p>${started}/14 modul pengkajian mulai diisi. Instrumen dipilih sesuai indikasi, kelengkapan bukan nilai kompetensi.</p><button class="btn light" data-go="interpretation">Telaah hasil instrumen</button></div>`}).join('')}<div class="card"><span class="eyebrow">Pendamping praktik</span><h3>${db.attendance.filter(x=>x.status==='Terverifikasi'&&x.presence==='Hadir').length} shift hadir terverifikasi</h3><p>${new Set(db.logs.filter(x=>x.status==='Terverifikasi'&&x.context==='Praktik klinik').map(x=>x.date)).size}/10 hari logbook klinik · ${db.reflections.filter(x=>x.status==='Terverifikasi').length}/2 refleksi.</p><button class="btn light" data-go="report">Laporan lengkap & PDF</button></div></div>`;};
function moduleCountForWeek(m,w){return Object.values(State.h2t[w]?.[m.id]||{}).some(f=>f.status||f.value||f.note);}
const fullReportBeforeV6=fullReportHTML;fullReportHTML=function(){fullReportBeforeV6();let root=$('#printReport');root.insertAdjacentHTML('beforeend',`<h2>J. Form penilaian kompetensi gerontik</h2><p class="report-note">Asesmen formatif preview berbasis draf RPS. Simulasi dan praktik klinik dibedakan. Bukan nilai akhir atau tanda tangan elektronik.</p>${competencyRecords().length?competencyRecords().map((x,i)=>`<h3>Form ${i+1} - ${esc(competencyName(x))}</h3>${competencyPDF(x)}`).join(''):'<p>Belum ada form kompetensi.</p>'}`);return root.innerHTML;};
function competencyPDF(x){let fields=[['skill','Kompetensi'],['date','Tanggal'],['week','Minggu'],['shift','Shift'],['room','Wisma'],['context','Konteks'],['action','Peran'],['method','Metode'],['supervisor','Pembimbing'],['caseCode','Kode kasus anonim'],['summary','Tindakan dan hasil'],['evidence','Bukti'],['reflection','Refleksi dan perbaikan'],['status','Status']];return fields.map(([k,l])=>`<div class="report-box"><strong>${l}</strong>\n${esc(x[k]||'[belum diisi]')}</div>`).join('')+(x.reviews||[]).map((r,i)=>`<h3>Review ${i+1}</h3><div class="report-box"><strong>Penilai dan waktu</strong>\n${esc(r.examiner)}; observasi ${esc(r.observed)}; pencatatan ${esc(r.at)}</div><table class="report-table"><thead><tr><th>Aspek rubrik ${esc(r.method||x.method)}</th><th>Skor / N/A</th></tr></thead><tbody>${RUBRICS[r.method||x.method].items.map(([l],i)=>`<tr><td>${esc(l)}</td><td>${esc(r.scores?.[i]|| (r.scores?.[i]===0?'0':'Belum dinilai'))}</td></tr>`).join('')}</tbody></table><div class="report-box"><strong>Hasil formatif</strong>\n${esc(r.decision)}; ${esc(r.outcome||'Belum ditetapkan')}; ${r.percent===null?'Belum dihitung':r.percent+'/100'}</div><div class="report-box"><strong>Umpan balik dan alasan N/A</strong>\n${esc(r.comment)}\n${esc(r.naReason||'Tidak ada aspek N/A')}</div>`).join('')+(x.history?.length?`<h3>Riwayat versi sebelumnya</h3>${x.history.map(h=>competencyPDF({...h,history:undefined})).join('')}`:'');}
const reviewBeforeV6=views.review;views.review=()=>reviewBeforeV6()+`<div class="card section"><h2>Penilaian kompetensi terstruktur</h2><p>${competencyRecords().filter(x=>x.status==='Diajukan').length} pengajuan menunggu observasi / penilaian.</p><button class="btn" data-go="competency">Buka form kompetensi →</button></div>`;
function enforceReadOnly(){if(!teacher())return;let mutations='[data-student],[data-demo],[data-hfield],[data-answer],[data-numeric],[data-clear-answer],[data-analysis],[data-plan],[data-care],[data-eval],[data-save-clinical],#newDx,#addAnalysis,#addPlan,[data-remove-plan],[data-remove-analysis]';$('#app').querySelectorAll(mutations).forEach(e=>{e.disabled=true});if(['demography','instruments','assessment','careplan','logbook','reflection','attendance','skin'].includes(page)){$('#app').insertAdjacentHTML('afterbegin','<div class="banner">Mode dosen · isian mahasiswa hanya dibaca pada halaman ini. Berikan penilaian melalui Form kompetensi atau Review pembimbing.</div>');if(page==='careplan')$('#app').querySelectorAll('textarea,input,select,button').forEach(e=>{if(!e.matches('[data-go],[data-clinical-week]'))e.disabled=true});$('#app').querySelectorAll('form').forEach(f=>f.querySelectorAll('input,textarea,select,button').forEach(e=>e.disabled=true));$('#app').querySelectorAll('[data-edit]').forEach(e=>e.disabled=true);}}
const renderBeforeV6=render;render=function(){competencyRecords();State=initClinical();renderBeforeV6();bindCompetency();enforceReadOnly();};
pages.splice(pages.findIndex(p=>p[0]==='logbook')+1,0,['competency','Form kompetensi']);
const goBeforeV6=go;go=function(p){if(p!==page)competencyEditing=null;goBeforeV6(p);};
$('#role').onchange=()=>{competencyEditing=null;render()};
document.title='Askep Gerontik Digital — Preview V6 Kompetensi & Dashboard Biru';render();

const pdfBeforeV6=geroPdfDefinition;geroPdfDefinition=function(root,info={}){let d=pdfBeforeV6(root,info);function inset(nodes){for(let node of nodes){if(node.stack)inset(node.stack);if(node.text&&node.alignment!=='center'){let m=node.margin||[0,0,0,0];if(typeof m==='number')m=[m,m,m,m];if(m.length===2)m=[m[0],m[1],m[0],m[1]];node.margin=[m[0],m[1],m[2]+3,m[3]];}}}inset(d.content);return d;};

